const PARENT_GUIDE_EDITS_BEFORE: Record<string, string> = {"progress-beyond-landing":"Progress is not linear. Every athlete will have ups and downs throughout their journey.\n\nI grew up hearing my dad frequently say that there is nothing like doing the same job twice you could've done right the first time.. and I think he hit the nail on the head when it comes to tumbling progressions. If we focus too much on acquiring a skill and not how it affects the next one. We can slow our long term progress down drastically by rushing through the process.\n\nFast is slow and slow is fast… \"Coach Jim\"\n\nFocusing on the right habits and consistency goes a much longer way than seeking shortcuts.\n\nTumbling has its hazards. When I am aware that a progression is more likely to increase the risk of injury, I feel morally obligated to guide athletes through the ones that reduce those risks instead. The tricky part is that the safest progressions that benefit athletes long term aren't always the most exciting to watch or go through. A slower, more technical path can look/feel like holding an athlete back when it's actually is often what's best for their long term progression and safety. If more athletes and parents understood that, I think they'd value when coaches slow the process down a lot more. Progress is not all about leveling up and getting new skills. Putting in consistent effort and making improvements that can feel like getting 1% better are the ones that add up to real long term growth.\n\nSlow and steady wins the race. Mastering the basics can often open the door to higher level tumbling more than just sending skills til they get it.","quiet-improvements":"Hand position, handstand lines, lunge lever handstand improvements. It's easy to overlook the small wins, but not every win is about getting a new skill. Speeding up a little on the handspring series, or hitting more accurate shapes in sequences we used last week, those are wins 100% worth acknowledging. Doing a few solid proper reps on a skill they've had for a while is still absolutely a win. I feel a real sense of gratification when I do a nice standing tuck even if it isn't my hardest skill.. Those reps are productive.","progress-question":"Did you learn anything?\n\nWhat's something that you know you can improve to get closer to your goal?\n\nWhat's something small you improved on?\n\nRyan says tumbling is full of unnatural feeling techniques. Any unnatural feeling corrections you've noticed are difficult that you can improve on??","basics-parent-asks":"The handstand is a staple in tumbling. The stronger the basics, the stronger the harder skills can be.","basics-unlocked-skill":"I had to go back to handsprings because I went straight to round off tucks. We can't really ever get a round off handspring double full if we never get a round off handspring. It's common for athletes to get stuck on round off handsprings because they learned their handspring before having a strong round off. It’s also common for athletes to get stuck on tucks because they worked it out of a round off before refining their round off handspring and series. Moving onto the RO hs lay without a strong round off handspring tuck creates challenges we can avoid by understanding and following the progression.\n\nThe stronger my layout is, the stronger my fulls and dubs can be.\n\nThe more accurate my shapes hit in a sequence like \"pike tuck hollow arch\", the stronger my shapes can be in an even faster tumbling sequence while passing through the upside down with a number of other things to think about.","perfection-before-progression":"This is an order of operation. Nothing is ever perfect.. the expression is a reminder to walk before you run. Set your standards high with prerequisites and your higher level skills will be easier to learn and achieve. Both tumble doc (Alvin Davis) and coach sahil (addicted to tumbling) have this philosophy written publicly.\n\nThere's a wabi-sabi saying I like: \"nothing is ever perfect, nothing is ever finished, and nothing lasts forever.\"","once-vs-owning":"Some coaches say once is luck, twice is a coincidence, and 3 times is a skill. I see it a little differently. Landing something once or even 3 times should absolutely be celebrated, but it doesn't quite equal owning the skill yet. Assuming an athlete will be able to hit the skill they landed a few times in one day can set them up for a tumbling block, especially when a cheer coach puts it in the routine or expects them to hit it at practice on command. It can make the athlete feel conditionally accepted, lead to injuries, increase fear and stress around the skill, and completely take the fun out of it. It can become an emotional rollercoaster and cause the athlete to doubt themselves on skills they've previously mastered. Just because an athlete hits a skill 3 times at practice doesn't mean it's time to put it in the routine. It takes consistent effort in maintaining and refining the skill to be ready to compete. There is a place between skill acquisition and mastery where a skill can begin to feel like second nature and be performed with minimal attention to detail after it has been done hundreds to thousands of times intentionally. And some skills may never feel like second nature. They can always feel unnatural and weird to perform and require thought and intention indefinitely.","stages-in-your-words":"Skill introduction, skill approximation, skill acquisition, skill mastery.","drill-decision":"The idea is that to perform a complex skill, we have to consider how quickly it happens and how much thought has to go into building the habits the movement requires. Our brain can't process more than 3-4 complex corrections, narrowed down to one word at a time, when the skill happens in less than 2 seconds. If we can break the movement into pieces, assign a handful of corrections to each piece, and build the habits to where we can do each piece correctly without having to think too much about it, then we can minimize how much simultaneous thought the skill demands. If I have 20 details to think about in 2 seconds, the details get lost. If I can master one piece of the movement with 2-3 corrections at a time, then another part, then another, at some point the skill becomes much easier for our brain to process and our body to perform. Training the full movement over and over without mastering its puzzle pieces can be a recipe for missing big important details because we are so focused on making it happen.. Deconstruction is an amazing tool for teaching and learning anything that requires complex understanding.","specific-explanation":"We learn the sequence \"pike hollow arch\" and we learn the cartwheel step in zombie so we can put them together as a connection drill. We build on the motions by doing the sequence out of a round off to zombie and eventually progress to a sweep through drill where we skip the zombie shape. This leads to athletes' ability to get their feet in front very easily when doing a round off back handspring connection.","more-attempts":"Repetition builds habits.. it's that simple.. repeating the same motion over and over and over and over does not always lead to improving the movement. It can actually be detrimental to the athlete's progress if they repeat the wrong motion over and over and build a habit that doesn't serve them. Repetition is important for building muscle memory and building habits. The movements we repeat need to be intentional in order for reps to build good habits.\n\nPractice itself doesn't always make perfect. Perfect practice makes perfect. I would much rather see an athlete do 5 clean and intentional handspring reps in a class that breaks the skill down than to see them send 15-20 reps that focus primarily on them getting a the flip over by themselves without preparing for what comes next.\n\nSometimes, if an athlete has trained it correctly, built the right habits and has mastered the drills, then it can become extremely beneficial to focus on more reps of the full skill since we are enforcing the right habits. I wouldn't say to stop doing the drills just because you got it down. keeping that drill fresh in your mind while doing the skill is also important. Repetition is important for developing muscle memory and correcting errors, but repetition could be the reason an athlete gets stuck with the wrong habits from doing them without correcting the movements which can be a real setback itself. it can sometimes take longer to correct bad habits than to teach good habits from the start. \"nothing like doing the same job twice you could have done right the first time\"","useful-homework":"Tumbling homework should always be something the athlete does because they are striving to improve, not because their parents make them do it. My hope is that as a coach, I tell the athletes why they need to work what they need to work well enough to the point they want to do it intrinsically on their own.  Useful homework is anything the athlete can do outside of classes/practice/lessons that will build up their tumbling. They could be doing intentional reps on the trampoline at home, practicing cartwheels, lunge lever handstands, studying shapes, watching reference videos, watching videos of their own tumbling, doing strength training, wall handstands.. drills you can do at home or even just intentionally focusing on the skill and thinking about how to improve it.","progress-not-perfection":"This is a mindset that encourages athletes to celebrate the small wins. Not prioritizing focus on leveling up rather than perfecting the skills they have. Perfection before progression does not contradict \"progress, not perfection\" the two mindsets can be held simultaneously. One is an order of operations, and one is a mindset. We don't skip the prerequisites that still need work and say \"progress not perfection\"…  and use that as a reason to stop striving to master the basics.","one-small-thing":"This depends on the athlete. I would look at what they need work on and base my answer off of that. Athletes generally can always improve their understanding of a skill by watching references.  Staying on top of some amount of conditioning and building up their hollow hold times, doing some extra work on core exercises or maybe I send them an arch to hollow exercise they can do for their back handsprings. sometimes I send a video that explains how twisting works.. Like most things, the answer is that it depends on the athlete.","move-up-criteria":"This depends on the athlete and the skill level and class that they are in. Not all gym’s require the same things for an athlete to move up. if they are ahead of the rest of the class and could benefit more from being in another class, this is more important than sticking to a clear criteria for them to master.. they need to be in an environment that challenges them and allows them to focus on what they need to be focused on. If they have mastered the criteria in the class and have what they need to work what is focused on in the next class, they move up.. sometimes we move an athlete up into a higher level class to keep them with athletes the same age as long as we can continue focusing on what that athlete needs.. the overall athlete experience is important to take into account for. What is best for the athlete’s progression is not always what is best to keep them in the program.. what is best for keeping them in the program is not always what is best for the athlete’s progression.","delayed-move-up":"Coach Lain said this one best.. \"sometimes where an athlete wants to be is not where an athlete needs to be.\"  For teams, we want to put the aces in their places.  For progression, we need to be in a class best suited for where they are in their tumbling journey. For this to not be troubling for athletes and parents, it's helpful to be reminded that all we can do is what is within our control. We can't control how fast we pick up on the techniques given to us by our coaches. Coaches can't control how fast an athlete progresses. We just stay true to the process, put our best foot forward (not literally.. for my right handed left tumblers) and do everything within our control to maximize what we take from practice with effort, pursuit of understanding, celebrating progress and staying patient.","ready-looks-like":"The athlete is killin it with the drills they're training, they have the skills the drills were meant to train them to perform and are performing the skills independently in ways that will complement the next skill. For teams, it is all based off of what their coaches decide. Sometimes gymnasts skip levels because of certain skills being too hard but harder skill being easier for them.. Sometimes a cheerleader moves up not because of tumbling, but because of stunting. Maybe they stay on a lower level team because they need more work in stunts even though they have the tumbling requirements for the next level. Sometimes an athlete is not mentally mature enough to move to a higher level team when their skills have advanced beyond their age. The goal is to put the athlete in a place that will maximize benefit for not only themselves, but for the team.","skill-goes-away":"There are several reasons this could happen.. trauma from falling or having an injury or watching someone get injured, maybe they are coming back from an injury and their body isn't physically ready.. Maybe they hit a growth spurt and the skill feels off. Pressure from coaches or parents or the feeling of conditional acceptance causes the athlete to shut down emotionally and enhances their self doubt. Bullying at school, getting a bad grade, overthinking, perfectionism and unwillingness to do a bad rep. maybe they didn't get it past the early acquisition phase and took some time off. Maybe they mastered it, hit puberty and then their hormones go haywire and affect their tumbling confidence.. sometimes the physiological responses we get from our nervous system can be completely out of our control and can hinder our ability to perform regardless of how well we understand the skill, how much we have trained it. whether or not we are prepared and have mastered it at practice. sometimes the environment can make an athlete struggle to perform a skill they have mastered. sometimes they just lose the feeling of skill because when they had it, they had a mental understanding of it that they are having trouble grasping again.. There are a number of reasons this could happen and every situation can be unique. Some of the most gratifying moments are when these types of athletes make a breakthrough.\n\nWhat should they do? It depends on the athlete and the reason why the skill feels lost. Sometimes it is a technique gap that needs filled in.. sometimes they just need a coach to listen to them. Sometimes they need to condition so they can gain the strength required for the skill if its from an injury or a growth spurt. There are many solutions to point to and pointing at the right one genuinely depends on the athlete and their situation.","fear-parents":"Unconditional support involves separating an athlete's value as a human from how they perform as an athlete. Be a safe place for them to talk. Be their anchor. Be the person that always is supportive not by providing coaching cues or telling them not to be scared.. but by listening and putting effort into understanding and helping them find resources that will help support their growth. Taking away all pressure and expectations of performance and providing hope, love, acceptance for where they are in the process, what they're going through emotionally, mentally and just being there to help however they can. Reminding them what is within their control and what is not and helping them to let go of outcomes out of their control and to focus solely on the process and things within their control that they can do.","small-wins":"Remind them that consistent effort over time plus small wins adds up over time. I was talking with Levi about this the other day.. It's almost like consistent progress focusing on the process like that can be like compounded interest. It stacks and stacks and the better they get, the more progress they make with the effort put in. I think there is like an S curve in the sense that it exponentially stacks progress but you can get to a point where you have gotten to such a high level of tumbling that any progress can only be small things. Adding a half turn to a triple full is much harder than adding a half twist to a layout. The main point is that explaining to athletes how those small wins are exactly what to be aiming for, it will help the athlete to focus on those kinds of wins and acknowledge and appreciate them.","car-ride-home":"This depends on the athlete, like most things. It depends on how they seem emotionally and what kind of adversities they could be going through, what has been going on surrounding practice or life. Some days for some athletes you might just wanna listen to music. You might ask them how it went, if they learned some good stuff or did any cool tricks. If you are a parent of an athlete who is struggling with fear on a skill and seems emotionally drained by it, these sometimes could be moments that open the door to conversations where you have to acknowledge the thing that must be frustrating, be as encouraging and supportive as you can, reminding them that as long as they are doing their best that is all they can do. It always comes back to doing what is within our control and trying not to get too hung up on outcomes we can't control. Saying things like \"did you throw your back handspring?\" or \"did you do your full?\" maybe aren't a great way of approaching the situation from the athlete's perspective if it is an emotionally draining situation for them. Just reading their body language and doing your best to intentionally be the best you can be for them is all the parents can do. Ultimately, parents know their athletes better than anyone and will have to just avoid making the car ride home add stress to the situation if possible.","worth-beyond-performance":"> Well… who we are is not exactly what skills we can do. We assign value to who we are, not to what physical capabilities we have or how fast we learn things. Is someone who never gets the skill worth less for who they are than the person who did get the skill? Sounds silly when you take it further. There is no shame in struggling to learn how to tumble. Now the feeling of gratification an athlete gets from knowing they hit a skill that was challenging for them is like the feeling adults get when we have a good day of work or get something productive done. There is a sense of gratification that comes with doing productive things at the end of the day, and days when we feel like we put in a bunch of work but get very little back is how it can feel to be an athlete who spent a tumbling session struggling to do what they were trying to do. So I think it's not as much about assigning self worth to their tumbling abilities sometimes. Sometimes it just can feel like work with no pay.\n>\n> Now I think during tryout season, I have seen this happen many times. Being the athlete that doesn't make the team can come with the sense that \"I am not good enough\" and can sting. Again though, the value of an athlete's sense of self worth should not be tied to what they are physically capable of, but when it comes to cheer tryouts, I think it can be hard for athletes to not have that initial feeling. We can't take it personally though. What could be much worse for some athletes would be to have made the team and then have a significant sense of added stress from what is expected of them when they aren't ready for those things to be expected from them. And many athletes experience this who do make it. I think it comes back to what coach Lain said: \"sometimes where an athlete wants to be is not where they need to be.\" That and the reminder that who we are is separate from our physical capabilities or our tumbling skills.","plateau-process":"> Sometimes an athlete can plateau when their physical capabilities are the limit. Sometimes it's that an athlete just needs a new approach.. sometimes they may not be stuck, they could just be in the middle of the process where things can feel slow. The fact that progress is not linear means that days that aren't as good are not setbacks.. just part of the process. You don't have to figure out if you're stuck.. you really just need to stay consistent with effort, pursuit of understanding and doing what is in your control and eventually the skill will happen if it's going to happen. there are some athletes that just don't get the handspring despite working on it for several years. But most athletes that work on it for several years and really seem like it might not happen, do get the handspring eventually at least on a trampoline.. It's amazing to see those athletes just keep going and end up getting the skill because they stayed consistent.","plateau-story":"I was stuck on kick fulls for a while.. what helped me unlock it were these three things..\n\n1. Realizing that the proper way of learning/doing the skill was going to involve resisting my natural instinct. I could not for the life of me understand aerial (late) twisting.. you have to really convince yourself you are not going to twist.. and resisting the urge to contact twist when that's what you're used to for regular fulls.. super hard.\n\n2. Reference videos.. along with a relentless pursuit of understanding, watching a slow mo video over and over of the skill I was learning helped so much with understanding the physical motion required.\n\n3. Alternating between prerequisites and the skill I was aiming for. I did 5 kick lays for every 1 kick full attempt for a WHILE... before I really could hit a kick full with a late twist. This worked for a lot of skills.. go back and forth between the building blocks and the actual skill and it helps bridge the gap between the movements.","choosing-class":"They should not be choosing the class, someone with expertise in the progression used at that gym should evaluate their tumbling and then put them in the right place for them to learn what they need to learn. For maximizing safety, technique and likelihood of complementing long term progression, I would personally say that parents should look for environments that offer skill deconstruction, encourage patience with progression, focus on strong prerequisites, and use gymnastics, tnt or powertumbling progressions.","class-purpose":"To shape young people into being more mentally resilient, hardworking, goal driven, patient with the process, and to consistently put in effort into things they enjoy, develop a sense of value in productivity, gain skills they can contribute to a team, learn to face adversities and to persevere when things are tough. We learn to face fears, to stay focused when the process isn't always gratifying.. there are so many life lessons that tumbling can be good for building on an athlete as a person. Ultimately, people do it because it is fun and thrilling to do things that can be dangerous in a controlled way.","faster-not-better":"Understanding that tumbling skills commonly take several years for athletes is important. Parents should know that. Coaches should know that. Athletes should know that. Gym owners should know that. It is not uncommon for it to take upwards of 3 years for an athlete to get a back handspring. Some skills can take longer for some athletes than it does for other athletes. The biggest thing I can come back to here is that the outcomes are less important than our habits and consistent efforts, determination, pursuit of understanding, and patience. We do our best and forget the rest!"};
const PARENT_GUIDE_EDITS_AFTER: Record<string, string> = {"progress-beyond-landing":"Progress is not linear. Every athlete will have ups and downs throughout their journey.\n\nI grew up hearing my dad frequently say that there is nothing like doing the same job twice you could've done right the first time, and I think he hit the nail on the head when it comes to tumbling progressions. If we focus too much on acquiring a skill and not how it affects the next one, we can slow our long term progress down drastically by rushing through the process.\n\nFast is slow and slow is fast… \"Coach Jim\"\n\nFocusing on the right habits and consistency goes a much longer way than seeking shortcuts.\n\nTumbling has its hazards. When I believe a progression exposes an athlete to unnecessary risk, I feel morally obligated to guide athletes through the ones that reduce those risks instead. The tricky part is that the progressions I believe are safest for long term development aren't always the most exciting to watch or go through. A slower, more technical path can look or feel like holding an athlete back when it's often what's actually best for their long term progression and safety. When athletes and parents understand that, I think they value it a lot more when coaches slow the process down. Progress is not all about leveling up and getting new skills. Putting in consistent effort and making improvements that can feel like getting 1% better are the ones that add up to real long term growth.\n\nSlow and steady wins the race. Mastering the basics can often open the door to higher level tumbling more than just sending skills til they get it.","quiet-improvements":"Hand position, handstand lines, lunge lever handstand improvements. It's easy to overlook the small wins, but not every win is about getting a new skill. Speeding up a little on the handspring series, or hitting more accurate shapes in sequences we used last week, those are wins 100% worth acknowledging. Doing a few solid proper reps on a skill they've had for a while is still absolutely a win. I feel a real sense of gratification when I do a nice standing tuck even if it isn't my hardest skill.. Those reps are productive.","progress-question":"Did you learn anything?\n\nWhat's something that you know you can improve to get closer to your goal?\n\nWhat's something small you improved on?\n\nTumbling is full of unnatural feeling techniques. Any unnatural feeling corrections you've noticed are difficult that you can improve on?","basics-parent-asks":"The handstand is a staple in tumbling. The stronger the basics, the stronger the harder skills can be.","basics-unlocked-skill":"I had to go back to handsprings because I went straight to round off tucks. We can't really ever get a round off handspring double full if we never get a round off handspring. It's common for athletes to get stuck on round off handsprings because they learned their handspring before having a strong round off. It’s also common for athletes to get stuck on tucks because they worked it out of a round off before refining their round off handspring and series. Moving onto the RO hs lay without a strong round off handspring tuck creates challenges we can avoid by understanding and following the progression.\n\nThe stronger my layout is, the stronger my fulls and dubs can be.\n\nThe more accurate my shapes hit in a sequence like \"pike tuck hollow arch\", the stronger my shapes can be in an even faster tumbling sequence while passing through the upside down with a number of other things to think about.","perfection-before-progression":"This is an order of operations. Nothing is ever literally perfect — the expression is a reminder to walk before you run. Set your standards high with prerequisites and your higher level skills will be easier to learn and achieve. Both tumble doc (Alvin Davis) and coach sahil (addicted to tumbling) have this philosophy written publicly.\n\nThere's a wabi-sabi saying I like: \"nothing is ever perfect, nothing is ever finished, and nothing lasts forever.\"","once-vs-owning":"Some coaches say once is luck, twice is a coincidence, and 3 times is a skill. I see it a little differently. Landing something once or even 3 times should absolutely be celebrated, but it doesn't quite equal owning the skill yet. Assuming an athlete will be able to hit the skill they landed a few times in one day can set them up for a tumbling block, especially when a cheer coach puts it in the routine or expects them to hit it at practice on command. It can make the athlete feel conditionally accepted, increase fear and stress around the skill, contribute to mental blocks, and completely take the fun out of it. It can also increase risk when an athlete feels pressured to perform something they don't feel ready for. It can become an emotional rollercoaster and cause the athlete to doubt themselves on skills they've previously mastered. Just because an athlete hits a skill 3 times at practice doesn't mean it's time to put it in the routine. It takes consistent effort in maintaining and refining the skill to be ready to compete. There is a place between skill acquisition and mastery where a skill can begin to feel like second nature and be performed with minimal attention to detail after it has been done hundreds to thousands of times intentionally. And some skills may never feel like second nature. They can always feel unnatural and weird to perform and require thought and intention indefinitely.","stages-in-your-words":"Skill introduction, skill approximation, skill acquisition, skill mastery.","drill-decision":"The idea is that to perform a complex skill, we have to consider how quickly it happens and how much thought has to go into building the habits the movement requires. There is only so much an athlete can consciously attend to during a movement that may last only a second or two. The more corrections we pile on simultaneously, the harder it becomes to act on any of them. If we can break the movement into pieces, assign a handful of corrections to each piece, and build the habits to where we can do each piece correctly without having to think too much about it, then we can minimize how much simultaneous thought the skill demands. If I have 20 details to think about in 2 seconds, the details get lost. If I can master one piece of the movement with 2-3 corrections at a time, then another part, then another, at some point the skill becomes much easier for our brain to process and our body to perform. Training the full movement over and over without mastering its puzzle pieces can be a recipe for missing big important details because we are so focused on making it happen.. Deconstruction is an amazing tool for teaching and learning anything that requires complex understanding.","specific-explanation":"We learn the sequence \"pike hollow arch\" and we learn the cartwheel step in zombie so we can put them together as a connection drill. We build on the motions by doing the sequence out of a round off to zombie and eventually progress to a sweep through drill where we skip the zombie shape. This leads to athletes' ability to get their feet in front very easily when doing a round off back handspring connection.","more-attempts":"Repetition builds habits.. it's that simple.. repeating the same motion over and over and over and over does not always lead to improving the movement. It can actually work against the athlete's progress if they repeat the wrong motion over and over and build a habit that doesn't serve them. Repetition is important for building muscle memory and building habits. The movements we repeat need to be intentional in order for reps to build good habits.\n\nPractice itself doesn't always make perfect. There's a familiar coaching saying — \"perfect practice makes perfect\" — and what it really points to is quality, intentionality, feedback, and correcting errors. I would much rather see an athlete do 5 clean and intentional handspring reps in a class that breaks the skill down than to see them send 15-20 reps that focus primarily on them getting a the flip over by themselves without preparing for what comes next.\n\nSometimes, if an athlete has trained it correctly, built the right habits and has mastered the drills, then it can become extremely beneficial to focus on more reps of the full skill since we are enforcing the right habits. I wouldn't say to stop doing the drills just because you got it down. keeping that drill fresh in your mind while doing the skill is also important. Repetition is important for developing muscle memory and correcting errors, but repetition could be the reason an athlete gets stuck with the wrong habits from doing them without correcting the movements which can be a real setback itself. it can sometimes take longer to correct bad habits than to teach good habits from the start. \"nothing like doing the same job twice you could have done right the first time\"","useful-homework":"My favorite kind of homework is eventually athlete driven. Parents can help by creating time and space to practice, reminding them, encouraging them, or even practicing alongside them, but I want the athlete's own desire to improve to become the main engine. My hope is that as a coach, I tell the athletes why they need to work what they need to work well enough to the point they want to do it intrinsically on their own.  Useful homework is anything the athlete can do outside of classes/practice/lessons that will build up their tumbling. They could be doing intentional reps on the trampoline at home, practicing cartwheels, lunge lever handstands, studying shapes, watching reference videos, watching videos of their own tumbling, doing strength training, wall handstands.. drills you can do at home or even just intentionally focusing on the skill and thinking about how to improve it.","progress-not-perfection":"This is a mindset that encourages athletes to celebrate the small wins. Not prioritizing focus on leveling up rather than perfecting the skills they have. Perfection before progression does not contradict \"progress, not perfection\" the two mindsets can be held simultaneously. One is an order of operations, and one is a mindset. We don't skip the prerequisites that still need work and say \"progress not perfection\"…  and use that as a reason to stop striving to master the basics.","one-small-thing":"This depends on the athlete. I would look at what they need work on and base my answer off of that. Athletes generally can always improve their understanding of a skill by watching references.  Staying on top of some amount of conditioning and building up their hollow hold times, doing some extra work on core exercises or maybe I send them an arch to hollow exercise they can do for their back handsprings. sometimes I send a video that explains how twisting works.. Like most things, the answer is that it depends on the athlete.","move-up-criteria":"This depends on the athlete and the skill level and class that they are in. Not all gym’s require the same things for an athlete to move up. if they are ahead of the rest of the class and could benefit more from being in another class, this is more important than sticking to a clear criteria for them to master.. they need to be in an environment that challenges them and allows them to focus on what they need to be focused on. If they have mastered the criteria in the class and have what they need to work what is focused on in the next class, they move up.. sometimes we move an athlete up into a higher level class to keep them with athletes the same age as long as we can continue focusing on what that athlete needs.. the overall athlete experience is important to take into account for. What is best for the athlete’s progression is not always what is best to keep them in the program.. what is best for keeping them in the program is not always what is best for the athlete’s progression.","delayed-move-up":"Coach Lain said this one best.. \"sometimes where an athlete wants to be is not where an athlete needs to be.\"  For teams, we want to put the aces in their places.  For progression, we need to be in a class best suited for where they are in their tumbling journey. For this to not be troubling for athletes and parents, it's helpful to be reminded that all we can do is what is within our control. We can't control how fast we pick up on the techniques given to us by our coaches. Coaches can't control how fast an athlete progresses. We just stay true to the process, put our best foot forward (not literally.. for my right handed left tumblers) and do everything within our control to maximize what we take from practice with effort, pursuit of understanding, celebrating progress and staying patient.","ready-looks-like":"The athlete is killin it with the drills they're training, they have the skills the drills were meant to train them to perform and are performing the skills independently in ways that will complement the next skill. For teams, it is all based off of what their coaches decide. Sometimes gymnasts skip levels because of certain skills being too hard but harder skill being easier for them.. Sometimes a cheerleader moves up not because of tumbling, but because of stunting. Maybe they stay on a lower level team because they need more work in stunts even though they have the tumbling requirements for the next level. Sometimes an athlete is not mentally mature enough to move to a higher level team when their skills have advanced beyond their age. The goal is to put the athlete in a place that will maximize benefit for not only themselves, but for the team.","skill-goes-away":"There are several reasons this could happen.. trauma from falling or having an injury or watching someone get injured, maybe they are coming back from an injury and their body isn't physically ready.. Maybe they hit a growth spurt and the skill feels off. Pressure from coaches or parents, or the feeling of conditional acceptance, can cause the athlete to shut down emotionally and enhance their self doubt. Bullying at school, getting a bad grade, overthinking, perfectionism and unwillingness to do a bad rep. maybe they didn't get it past the early acquisition phase and took some time off. Maybe they mastered it, then hit a growth spurt — changing body proportions, strength-to-weight shifts, and coordination changes can all make a skill feel different for a while, which can shake their tumbling confidence. Sometimes the physiological responses we get from our nervous system can be completely out of our control and can hinder our ability to perform regardless of how well we understand the skill, how much we have trained it. whether or not we are prepared and have mastered it at practice. sometimes the environment can make an athlete struggle to perform a skill they have mastered. sometimes they just lose the feeling of skill because when they had it, they had a mental understanding of it that they are having trouble grasping again.. There are a number of reasons this could happen and every situation can be unique. Some of the most gratifying moments are when these types of athletes make a breakthrough.\n\nWhat should they do? It depends on the athlete and the reason why the skill feels lost. Sometimes it is a technique gap that needs filled in.. sometimes they just need a coach to listen to them. Sometimes they need to condition so they can gain the strength required for the skill if its from an injury or a growth spurt. There are many solutions to point to and pointing at the right one genuinely depends on the athlete and their situation.","fear-parents":"Unconditional support involves separating an athlete's value as a human from how they perform as an athlete. Be a safe place for them to talk. Be their anchor. Be the person that always is supportive not by providing coaching cues or telling them not to be scared.. but by listening and putting effort into understanding and helping them find resources that will help support their growth. Taking away all pressure and expectations of performance and providing hope, love, acceptance for where they are in the process, what they're going through emotionally, mentally and just being there to help however they can. Reminding them what is within their control and what is not and helping them to let go of outcomes out of their control and to focus solely on the process and things within their control that they can do.","small-wins":"Remind them that consistent effort over time plus small wins adds up over time. I was talking with Levi about this the other day.. It's almost like consistent progress focusing on the process like that can be like compounded interest. It stacks and stacks and the better they get, the more progress they make with the effort put in. I think there is like an S curve in the sense that it exponentially stacks progress but you can get to a point where you have gotten to such a high level of tumbling that any progress can only be small things. Adding a half turn to a triple full is much harder than adding a half twist to a layout. The main point is that explaining to athletes how those small wins are exactly what to be aiming for, it will help the athlete to focus on those kinds of wins and acknowledge and appreciate them.","car-ride-home":"This depends on the athlete, like most things. It depends on how they seem emotionally and what kind of adversities they could be going through, what has been going on surrounding practice or life. Some days for some athletes you might just wanna listen to music. You might ask them how it went, if they learned some good stuff or did any cool tricks. If you are a parent of an athlete who is struggling with fear on a skill and seems emotionally drained by it, these sometimes could be moments that open the door to conversations where you have to acknowledge the thing that must be frustrating, be as encouraging and supportive as you can, reminding them that as long as they are doing their best that is all they can do. It always comes back to doing what is within our control and trying not to get too hung up on outcomes we can't control. Saying things like \"did you throw your back handspring?\" or \"did you do your full?\" maybe aren't a great way of approaching the situation from the athlete's perspective if it is an emotionally draining situation for them. Just reading their body language and doing your best to intentionally be the best you can be for them is all the parents can do. Ultimately, parents know their athletes better than anyone and will do their best to keep the car ride home from adding stress to the situation if possible.","worth-beyond-performance":"> Well… who we are is not exactly what skills we can do. We assign value to who we are, not to what physical capabilities we have or how fast we learn things. Is someone who never gets the skill worth less for who they are than the person who did get the skill? Sounds silly when you take it further. There is no shame in struggling to learn how to tumble. Now the feeling of gratification an athlete gets from knowing they hit a skill that was challenging for them is like the feeling adults get when we have a good day of work or get something productive done. There is a sense of gratification that comes with doing productive things at the end of the day, and days when we feel like we put in a bunch of work but get very little back is how it can feel to be an athlete who spent a tumbling session struggling to do what they were trying to do. So I think it's not as much about assigning self worth to their tumbling abilities sometimes. Sometimes it just can feel like work with no pay.\n>\n> Now I think during tryout season, I have seen this happen many times. Being the athlete that doesn't make the team can come with the sense that \"I am not good enough\" and can sting. Again though, the value of an athlete's sense of self worth should not be tied to what they are physically capable of, but when it comes to cheer tryouts, I think it can be hard for athletes to not have that initial feeling. We can't take it personally though. What could be much worse for some athletes would be to have made the team and then have a significant sense of added stress from what is expected of them when they aren't ready for those things to be expected from them. And many athletes experience this who do make it. I think it comes back to what coach Lain said: \"sometimes where an athlete wants to be is not where they need to be.\" That and the reminder that who we are is separate from our physical capabilities or our tumbling skills.","plateau-process":"> Sometimes an athlete can plateau when their physical capabilities are the limit. Sometimes it's that an athlete just needs a new approach.. sometimes they may not be stuck, they could just be in the middle of the process where things can feel slow. The fact that progress is not linear means that days that aren't as good are not setbacks.. just part of the process. You don't have to figure out if you're stuck.. you really just need to stay consistent with effort, pursuit of understanding and doing what is in your control and eventually the skill will happen if it's going to happen. there are some athletes that just don't get the handspring despite working on it for several years. But most athletes that work on it for several years and really seem like it might not happen, do get the handspring eventually at least on a trampoline.. It's amazing to see those athletes just keep going and end up getting the skill because they stayed consistent.","plateau-story":"I was stuck on kick fulls for a while.. what helped me unlock it were these three things..\n\n1. Realizing that the proper way of learning/doing the skill was going to involve resisting my natural instinct. I could not for the life of me understand aerial (late) twisting.. you have to really convince yourself you are not going to twist.. and resisting the urge to contact twist when that's what you're used to for regular fulls.. super hard.\n\n2. Reference videos.. along with a relentless pursuit of understanding, watching a slow mo video over and over of the skill I was learning helped so much with understanding the physical motion required.\n\n3. Alternating between prerequisites and the skill I was aiming for. I did 5 kick lays for every 1 kick full attempt for a WHILE... before I really could hit a kick full with a late twist. This worked for a lot of skills.. go back and forth between the building blocks and the actual skill and it helps bridge the gap between the movements.","choosing-class":"Parents should absolutely be part of the conversation — you know your child's schedule, happiness, social environment, goals, stress, and life outside the gym in ways a coach may never see. The technical placement itself is usually best guided by someone who understands that gym's progression system and has evaluated the athlete, then put them in the right place for them to learn what they need to learn. For maximizing safety, technique and likelihood of complementing long term progression, I would personally say that parents should look for environments that offer skill deconstruction, encourage patience with progression, focus on strong prerequisites, and use gymnastics, tnt or powertumbling progressions.","class-purpose":"To shape young people into being more mentally resilient, hardworking, goal driven, patient with the process, and to consistently put in effort into things they enjoy, develop a sense of value in productivity, gain skills they can contribute to a team, learn to face adversities and to persevere when things are tough. We learn to face fears, to stay focused when the process isn't always gratifying.. there are so many life lessons that tumbling can be good for building on an athlete as a person. Ultimately, people do it because it is fun and thrilling to do things that can be dangerous in a controlled way.","faster-not-better":"Understanding that tumbling skills commonly take several years for athletes is important. Parents should know that. Coaches should know that. Athletes should know that. Gym owners should know that. In my coaching, I have seen some athletes work for years on a back handspring — it is not uncommon for it to take upwards of 3 years for an athlete to get one. Some skills can take longer for some athletes than it does for other athletes. The biggest thing I can come back to here is that the outcomes are less important than our habits and consistent efforts, determination, pursuit of understanding, and patience. We do our best and forget the rest!"};

let parentGuideMigrationDone = false;

async function migrateParentGuideEdits(current: CoachInterviewFile): Promise<CoachInterviewFile> {
  if (parentGuideMigrationDone) return current;
  parentGuideMigrationDone = true;
  const answers = { ...current.answers };
  let changed = false;
  for (const key of Object.keys(PARENT_GUIDE_EDITS_AFTER)) {
    const live = (answers[key] || '').trim();
    if (!live) continue;
    if (live === PARENT_GUIDE_EDITS_AFTER[key]) continue;
    if (live === PARENT_GUIDE_EDITS_BEFORE[key]) {
      answers[key] = PARENT_GUIDE_EDITS_AFTER[key];
      changed = true;
    }
  }
  if (!changed) return current;
  const next: CoachInterviewFile = {
    ...current,
    answers,
    updatedAt: new Date().toISOString(),
  };
  await writeJson(FILE, next);
  return next;
}

export async function readCoachInterviewFile(): Promise<CoachInterviewFile> {
  const data = await readJson<CoachInterviewFile>(FILE, { ...EMPTY })
  if (!data || data.kind !== 'shape-lab-coach-interview' || typeof data.answers !== 'object') {
    return { ...EMPTY }
  }
  return migrateParentGuideEdits(data)
}

export async function writeCoachInterviewFile(data: unknown): Promise<CoachInterviewFile> {
  const parsed = data as Partial<CoachInterviewFile>
  const answers: Record<string, string> = {}
  const incoming = parsed.answers && typeof parsed.answers === 'object' ? parsed.answers : {}
  for (const [id, text] of Object.entries(incoming)) {
    if (!id || typeof text !== 'string') continue
    const trimmed = text.trim()
    if (trimmed) answers[id] = text
  }
  const next: CoachInterviewFile = {
    kind: 'shape-lab-coach-interview',
    version: 1,
    updatedAt: new Date().toISOString(),
    answers,
  }
  await writeJson(FILE, next)
  return next
}
